def _env_ceiling(noise_disp: str | None, rt60_disp: str | None) -> int:
    """The ENVIRONMENTAL upper bound on audio_tier from the screening dispositions
    (Rick, 2026-06-28): noise WARN → 2 (Lo-fi), noise CAUTION → 3 (Production), RT60
    borderline → 2 (Lo-fi), RT60 production → 3 (Production). PASS / clean → no cap.
    REJECT never reaches here (it fails the stage gate). Applied at the MATRIX ONLY
    (not the audio-review score).

    `production` is the fourth RT60 band (audio band policy AB-2, Rick 2026-07-30),
    emitted only under a profile carrying gate.production_below. It maps to 3 rather
    than 2 — that IS the point of the band: a room that used to be refused outright now
    lands one rung down instead of off the ladder. Whichever of noise/RT60 comes in
    lower sets the ceiling, which is the min() already implemented here.

    REJECT branches (Rick 2026-07-30): on THIS audition/matrix path they stay
    unreachable — a REJECT fails the stage gate and never earns a disposition to cap.
    But the same function computes the per-segment ADVISORY `would_cap_at`
    (downstream._fidelity), where the noise scan is annotation and never gates, so
    REJECT does arrive there. Without a branch it fell through to cap 4 — NO cap —
    and the noisiest segment on the local box (17.99 dB SNR) read Hi-fi while a 42 dB
    segment read Lo-fi. The cap must be monotonic in the measurement: worse can never
    read higher. RT60 `error` deliberately takes no branch — could-not-measure is
    not bad, it is unknown (the AB-7′ dry-room class)."""
    cap = 4
    nd = (noise_disp or "").upper()
    if nd in ("WARN", "REJECT"):
        cap = min(cap, 2)
    elif nd == "CAUTION":
        cap = min(cap, 3)
    rd = (rt60_disp or "").lower()
    if rd in ("borderline", "reject"):
        cap = min(cap, 2)
    elif rd == "production":
        cap = min(cap, 3)
    return cap


def _device_ceiling(is_mobile: bool | None) -> int:
    """The DEVICE upper bound on audio_tier (D-TC1, Rick 2026-07-04): a mobile-device
    capture caps at 2 (Lo-fi). Phone mics are physically lo-fi regardless of sample-rate
    honesty — a Pixel records spectrally-native 48k yet phone-grade, so the spectral
    (format) verifier passes it and the device flag is the necessary complement. ALWAYS
    ON, no toggle (D-TC2): phone quality never earns editing time to be promoted.
    `is_mobile` is the browser's UA self-report (capint-1), stamped on the take's
    capture_integrity provenance."""
    return 2 if is_mobile else 4
